namespace {bool watch=false;uint64_t allocations=0;void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}class Original:public H8SEmulator{public:void histories(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t clocks;unsigned at;uint8_t value;bool write;};
template<class D>struct Tape{D&d;bool overlay=false,recording=false,context=false,trampoline=false;unsigned count=0,lcdBusy=2,phasePc=0;uint8_t buttons=0xff;std::array<Event,16>events{};explicit Tape(D&s):d(s){}void record(unsigned a,uint8_t v,bool w){if(!recording||!w&&a>=phasePc&&a<phasePc+12||context&&a>=0xfffea0&&a<0xffff10||trampoline&&!w&&a>=0xfffd10&&a<0xfffd1c)return;check(count<events.size(),"Tape overflow");events[count++]={d.cycles,a,v,w};}uint8_t read(unsigned a){auto v=d.memory[a<0x10000&&overlay?0x400000+a:a];if(a==0xffffc7)v=d.memory[0xffffd3]==0x10?buttons:lcdBusy?(--lcdBusy,0x80):0;record(a,v,false);return v;}void write(unsigned a,uint8_t v){record(a,v,true);d.memory[a]=v;if(a==0xffffcf)overlay=!(v&1);}};
struct OldBus:H8SDevice{Tape<Original>&t;explicit OldBus(Tape<Original>&s):t(s){}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct NewBus:kstation::ControllerResourceBus{Tape<kstation::ControllerDeviceState>&t;explicit NewBus(Tape<kstation::ControllerDeviceState>&s):t(s){}bool mapped(unsigned a)const override{return a<0x10000||a>=0x200000&&a<0x240000||a>=0x400000&&a<0x420000||a>=0xfffd00;}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct Fixture{std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::ControllerDeviceState>d=std::make_unique<kstation::ControllerDeviceState>();Tape<Original>x{*a};Tape<kstation::ControllerDeviceState>y{*d};OldBus xb{x};NewBus yb{y};kstation::ControllerStartupBannerRuntime native;kstation::ControllerLcdRuntime lcd;kstation::ControllerNumericDisplayRuntime numeric;kstation::ControllerInterruptRuntime irq;bool early=false;uint64_t phases=0,io=0,shorts=0;void byte(unsigned at,unsigned v){a->memory[at&0xffffff]=d->memory[at&0xffffff]=uint8_t(v);}void wide(unsigned at,unsigned v){for(unsigned i=0;i<4;++i)byte(at+i,v>>(8*(3-i)));}
Fixture(const std::vector<uint8_t>&rom,bool boot=false):early(boot){a->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!early)for(unsigned i=0;i<rom.size();++i)byte(0x400000+i,rom[i]);for(auto p:{std::pair{0,0x10000},std::pair{0x400000,0x20000},std::pair{0xfffd00,0x300}})a->memmap(&xb,p.first,p.second);d->attachBus(&yb);if(early){irq.setMask(kstation::ControllerInterruptRuntime::Mask::Disabled);check(native.bindBootResources(*d,rom.data(),rom.size()),"Banner boot bind");}else{check(irq.bindVerifiedFirmware(*d,rom.data(),rom.size()),"IRQ bind");check(native.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Banner bind");}check(lcd.bindBootResources(*d,rom.data(),rom.size()),"LCD bind");check(numeric.bindBootResources(*d,rom.data(),rom.size()),"Numeric bind");}
void prepare(unsigned entry,unsigned flags,unsigned buttons){native.reset();lcd.reset();numeric.reset();a->pc=a->makepc(entry);a->setSP(0xffff00);wide(0xffff00,0x3ae8);a->ccr=uint8_t(flags|(early?128u:0u));a->histories(-1,-1);d->lastRead=d->lastWrite=-1;a->cycles=d->cycles=flags==255?~uint64_t(0)-7:100000;a->pending_irqs=d->pendingIrqs=flags==255?uint64_t(1)<<38:0;irq.setMask((early||flags&128)?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);x.buttons=y.buttons=uint8_t(buttons);x.lcdBusy=y.lcdBusy=2;x.recording=y.recording=true;auto source=entry==0x1456?0x138u:0xce1eu;byte(0xce1e,flags);byte(0xce1f,flags*73+11);a->reg32(6)=int32_t(source);a->reg8(13)=int8_t(flags*73+11);using K=kstation::ControllerStartupBannerRuntime::Kind;check(native.start(entry==0x1456?K::Banner:entry==0x14b6?K::Base:entry==0x14b2?K::Full:K::Minor,source,uint8_t(flags*73+11)),"Banner start");}
void run(){watch=true;for(unsigned i=0;native.active()&&i<3000000;++i){auto pc=unsigned(a->getPC());x.context=y.context=true;x.phasePc=y.phasePc=pc&0xffffff;x.count=y.count=0;auto n=native.nextClocks(*d,irq,numeric,lcd);if(i<70||i%1009==0){auto snapshot=native;auto cycle=d->cycles;int read=d->lastRead,write=d->lastWrite;for(unsigned b=0;b<n;++b){check(!native.advanceBefore(*d,irq,numeric,lcd,b).clocks,"Banner short accepted");check(!std::memcmp(&snapshot,&native,sizeof(native))&&cycle==d->cycles&&read==d->lastRead&&write==d->lastWrite&&!x.count&&!y.count,"Banner short mutated");++shorts;}}check(native.advanceBefore(*d,irq,numeric,lcd,n).clocks,"Banner refused");a->step();if(a->cycles!=d->cycles){std::fprintf(stderr,"PC%x clocks%llu/%llu\n",pc,a->cycles,d->cycles);throw std::runtime_error("Banner clocks");}if(x.count!=y.count){std::fprintf(stderr,"PC%x count%u/%u\n",pc,x.count,y.count);throw std::runtime_error("Banner IO count");}for(unsigned j=0;j<x.count;++j){auto&p=x.events[j];auto&q=y.events[j];if(!(p.clocks==q.clocks&&p.at==q.at&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"PC%x addr%x/%x value%x/%x time%llu/%llu\n",pc,p.at,q.at,p.value,q.value,p.clocks,q.clocks);throw std::runtime_error("Banner ordered IO");}}io+=x.count;++phases;}watch=false;check(!native.active()&&a->getPC()==0x3ae8,"Banner runaway");for(auto p:{std::pair{0xfffd10,0x190},std::pair{0xffff10,0xf0}})check(!std::memcmp(a->memory+p.first,d->memory+p.first,p.second),"Banner memory differs");}
};}
void*operator new(size_t n){if(watch)++allocations;if(auto*p=std::malloc(n))return p;throw std::bad_alloc();}void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}
int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};Fixture f(rom);unsigned cases=0;for(unsigned flags:{0u,255u})for(unsigned buttons:{0xbfu,0xffu}){f.prepare(0x1456,flags,buttons);f.run();++cases;}for(unsigned entry:{0x14b2u,0x14b6u,0x14d8u})for(unsigned flags=0;flags<256;++flags){f.prepare(entry,flags,0xff);f.run();++cases;}Fixture boot(rom,true);for(unsigned flags=0;flags<256;++flags){boot.prepare(0x14b2,flags,0xff);boot.run();++cases;}f.phases+=boot.phases;f.io+=boot.io;f.shorts+=boot.shorts;check(!allocations,"Banner processing allocation");std::printf("{\"passed\":true,\"graphs\":%u,\"native_phases\":%llu,\"ordered_io\":%llu,\"short_budgets\":%llu,\"processing_allocations\":%llu}\n",cases,f.phases,f.io,f.shorts,allocations);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
